	@Test
	public void exclusivePathCloneRetainsMetadataAndOwnsMutableChildren() {
		QueryInfo query = mock(QueryInfo.class);
		StatementSource source = new StatementSource("member", StatementSourceType.REMOTE);
		ExclusiveArbitraryLengthPath original = new ExclusiveArbitraryLengthPath(
				new ArbitraryLengthPath(StatementPattern.Scope.DEFAULT_CONTEXTS, Var.of("start"),
						new StatementPattern(Var.of("start"), Var.of("predicate"), Var.of("end")), Var.of("end"),
						null, 1),
				source, query);
		Dataset dataset = new SimpleDataset();
		ResolvedGraphSelection selection = new ResolvedGraphSelection(RDF4J.NIL, RDF4J.NIL, true);
		original.setExecutionDataset(dataset);
		original.setResolvedGraphSelection(selection);
		original.setVariableScopeChange(true);
		original.setCostEstimate(2.5);
		original.setResultSizeEstimate(4.0);
		original.setResultSizeActual(3);
		original.setRuntimeTelemetryEnabled(true);
		original.setStringMetricPlanned("selected", "metadata");
		original.setQueryModelMetadata("optimizer", "retained");

		ExclusiveArbitraryLengthPath copy = original.clone();

		assertThat(copy.isVariableScopeChange()).isTrue();
		assertThat(copy.getCostEstimate()).isEqualTo(2.5);
		assertThat(copy.getResultSizeEstimate()).isEqualTo(4.0);
		assertThat(copy.getResultSizeActual()).isEqualTo(3);
		assertThat(copy.isRuntimeTelemetryEnabled()).isTrue();
		assertThat(copy.getStringMetricPlanned("selected")).isEqualTo("metadata");
		assertThat(copy.getQueryModelMetadata("optimizer")).isEqualTo("retained");
		assertThat(copy.getExecutionDataset()).isSameAs(dataset);
		assertThat(copy.getResolvedGraphSelection()).isSameAs(selection);
		assertThat(copy.getQueryInfo()).isSameAs(query);
		assertThat(copy.getOwner()).isSameAs(source);
		assertThat(copy.getPathExpression()).isNotSameAs(original.getPathExpression());
		assertThat(copy.getPathExpression().getParentNode()).isSameAs(copy);
		assertThat(original.getPathExpression().getParentNode()).isSameAs(original);
		assertThat(copy.getFreeVars()).isNotSameAs(original.getFreeVars());
		copy.getFreeVars().add("copyOnly");
		assertThat(original.getFreeVars()).doesNotContain("copyOnly");
	}

