	@Test
	public void exclusiveGroupClonePreservesAnnotationsAndOwnsStatements() {
		QueryInfo query = mock(QueryInfo.class);
		FederationContext federation = mock(FederationContext.class);
		EndpointManager endpoints = mock(EndpointManager.class);
		when(query.getFederationContext()).thenReturn(federation);
		when(federation.getEndpointManager()).thenReturn(endpoints);
		when(endpoints.getEndpoint("member")).thenReturn(mock(Endpoint.class));
		StatementSource source = new StatementSource("member", StatementSourceType.REMOTE);
		ExclusiveStatement statement = new ExclusiveStatement(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				source, query);
		Dataset executionDataset = new SimpleDataset();
		statement.setExecutionDataset(executionDataset);
		ExclusiveGroup original = new ExclusiveGroup(List.of(statement), source, query);
		original.setExecutionDataset(executionDataset);
		ExclusiveGroup copy = original.clone();
		assertThat(copy.getOwner()).isEqualTo(source);
		assertThat(copy.getQueryInfo()).isSameAs(query);
		ExclusiveStatement copied = (ExclusiveStatement) copy.getExclusiveExpressions().getFirst();
		assertThat(copied).isNotSameAs(statement);
		assertThat(copy.getExecutionDataset()).isSameAs(executionDataset);
		assertThat(copied.getExecutionDataset()).isSameAs(executionDataset);
		assertThat(copied.getParentNode()).isSameAs(copy);
		assertThat(statement.getParentNode()).isSameAs(original);
		copied.replaceChildNode(copied.getSubjectVar(),
				Var.of("s", SimpleValueFactory.getInstance().createIRI("urn:s")));
		assertThat(statement.getScope()).isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
		assertThat(statement.getSubjectVar().hasValue()).isFalse();
	}

