	@Test
	public void replacingOrdinaryStatementInvalidatesCachedBindings() {
		QueryInfo query = mock(QueryInfo.class);
		TripleRefStatementPattern tripleRef = new TripleRefStatementPattern(
				new StatementPattern(Var.of("subject"), Var.of("predicate"), Var.of("triple")),
				new TripleRef(Var.of("tripleSubject"), Var.of("triplePredicate"), Var.of("tripleObject"),
						Var.of("triple")),
				query);
		StatementPattern originalStatement = new StatementPattern(Var.of("oldSubject"), Var.of("oldPredicate"),
				Var.of("oldObject"));
		TripleRefJoinGroup group = new TripleRefJoinGroup(tripleRef, List.of(originalStatement), List.of(), query);

		group.getAssuredBindingNames();
		group.getFreeVars();

		StatementPattern replacement = new StatementPattern(Var.of("newSubject"), Var.of("newPredicate"),
				Var.of("newObject"));
		group.replaceChildNode(originalStatement, replacement);

		assertThat(replacement.getParentNode()).isSameAs(group);
		assertThat(group.getAssuredBindingNames()).contains("newSubject", "newPredicate", "newObject")
				.doesNotContain("oldSubject", "oldPredicate", "oldObject");
		assertThat(group.getFreeVars()).contains("newSubject", "newPredicate", "newObject")
				.doesNotContain("oldSubject", "oldPredicate", "oldObject");
	}

