	@Test
	public void federatedStatementCloneOwnsExistsFilterTree() {
		QueryInfo query = mock(QueryInfo.class);
		StatementSource source = new StatementSource("member", StatementSourceType.REMOTE);
		StatementPattern innerPattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		Exists exists = new Exists(innerPattern);
		FilterExpr filter = new FilterExpr(exists, new HashSet<>(List.of("s", "p", "o")));
		ExclusiveStatement original = new ExclusiveStatement(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("outerObject")), source, query);
		original.addFilterExpr(filter);

		ExclusiveStatement copy = (ExclusiveStatement) original.clone();
		FilterExpr copiedFilter = (FilterExpr) copy.getFilterExpr();
		Exists copiedExists = (Exists) copiedFilter.getExpression();
		StatementPattern copiedInnerPattern = (StatementPattern) copiedExists.getSubQuery();
		copiedInnerPattern.replaceWith(new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				copiedInnerPattern.getSubjectVar().clone(), copiedInnerPattern.getPredicateVar().clone(),
				copiedInnerPattern.getObjectVar().clone()));
		copiedFilter.getVars().add("copyOnly");

		assertThat(copiedFilter).isNotSameAs(filter);
		assertThat(copiedExists).isNotSameAs(exists);
		assertThat(copiedFilter.getVars()).isNotSameAs(filter.getVars());
		assertThat(filter.getVars()).doesNotContain("copyOnly");
		assertThat(copiedExists.getSubQuery().getParentNode()).isSameAs(copiedExists);
		assertThat(exists.getSubQuery().getParentNode()).isSameAs(exists);
		assertThat(innerPattern.getScope()).isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
	}

	@Test
	public void federatedStatementCloneOwnsConjunctiveFilterTrees() {
		QueryInfo query = mock(QueryInfo.class);
		StatementSource source = new StatementSource("member", StatementSourceType.REMOTE);
		StatementPattern firstInner = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("firstObject"));
		StatementPattern secondInner = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("secondObject"));
		FilterExpr firstFilter = new FilterExpr(new Exists(firstInner), new HashSet<>(List.of("s", "p")));
		FilterExpr secondFilter = new FilterExpr(new Exists(secondInner), new HashSet<>(List.of("s", "p")));
		ExclusiveStatement original = new ExclusiveStatement(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("outerObject")), source, query);
		original.addFilterExpr(firstFilter);
		original.addFilterExpr(secondFilter);

		ExclusiveStatement copy = (ExclusiveStatement) original.clone();
		ConjunctiveFilterExpr copiedConjunction = (ConjunctiveFilterExpr) copy.getFilterExpr();
		Exists copiedExists = (Exists) copiedConjunction.getExpressions().get(0).getExpression();
		StatementPattern copiedInner = (StatementPattern) copiedExists.getSubQuery();
		copiedInner.replaceWith(new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				copiedInner.getSubjectVar().clone(), copiedInner.getPredicateVar().clone(),
				copiedInner.getObjectVar().clone()));

		assertThat(copiedConjunction.getExpressions())
				.isNotSameAs(((ConjunctiveFilterExpr) original.getFilterExpr()).getExpressions());
		assertThat(copiedConjunction.getExpressions().get(0)).isNotSameAs(firstFilter);
		assertThat(copiedConjunction.getExpressions().get(1)).isNotSameAs(secondFilter);
		assertThat(copiedExists).isNotSameAs(firstFilter.getExpression());
		assertThat(copiedExists.getSubQuery().getParentNode()).isSameAs(copiedExists);
		assertThat(((StatementPattern) ((Exists) firstFilter.getExpression()).getSubQuery()).getScope())
				.isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
		assertThat(((StatementPattern) ((Exists) secondFilter.getExpression()).getSubQuery()).getScope())
				.isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
	}

